25	// reqWhitespaceCLIRecord 构造合法记录：学生 "s1" 与 " s1 "、课程
26	// "c1"（高等数学 4 学分）与 " c1 "（大学物理 3 学分）；"s1" 名下
27	// 已有要求 r1 指向 "c1"，" s1 " 名下尚无要求。
28	func reqWhitespaceCLIRecord() *diskRecord {
29		return &diskRecord{
30			Version: 1,
31			Courses: []diskCourse{
32				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
33				{ID: " c1 ", Name: "大学物理", Credit: 3, Open: true},
34			},
35			Students: []diskStudent{{ID: "s1"}, {ID: " s1 "}},
36			Requirements: []diskReq{
37				{ID: "r1", Student: "s1", Course: "c1"},
38			},
