40	}
41	
42	// TestCLIReqWhitespaceAllIDsPreserved 题目主场景：为 " s1 " 登记指向
43	// " c1 " 的要求 " r1 "，只在该学生名下保存一份，三个编号原文保留；
44	// show 显示完整要求编号与实际指向课程的名称、学分；"s1" 的要求与
45	// 学分保持原样。
46	func TestCLIReqWhitespaceAllIDsPreserved(t *testing.T) {
47		file, _ := writeDiskRecord(t, reqWhitespaceCLIRecord())
48	
49		out, errText, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 ")
50		if code != 0 {
51			t.Fatalf("登记应成功，code=%d out=%q err=%q", code, out, errText)
52		}
53		if !strings.Contains(out, "已为学生  s1  登记要求  r1 ，指向课程  c1 ") {
54			t.Fatalf("成功提示应保留三个编号原文，out=%q", out)
55		}
56	
57		// show " s1 "：完整要求编号 + 实际指向课程 " c1 " 的名称、学分。
58		out, _, code = runCLI(t, file, "show", " s1 ")
59		if code != 0 {
60			t.Fatalf("show \" s1 \" 应成功，code=%d out=%q", code, out)
61		}
62		if !strings.Contains(out, "要求  r1  -> 课程  c1 《大学物理》3 学分") {
63			t.Fatalf("应显示完整要求编号与实际课程名称、学分，out=%q", out)
64		}
65		if strings.Contains(out, "高等数学") {
66			t.Fatalf("\" s1 \" 的要求不应指向 \"s1\" 的课程 c1，out=%q", out)
67		}
68	
69		// "s1" 的要求与课程指向保持原样。
70		out, _, code = runCLI(t, file, "show", "s1")
71		if code != 0 || !strings.Contains(out, "要求 r1 -> 课程 c1《高等数学》4 学分") {
72			t.Fatalf("\"s1\" 的要求应保持原样，code=%d out=%q", code, out)
73		}
74		if strings.Contains(out, "要求  r1  -> 课程  c1 ") || strings.Contains(out, "大学物理") {
75			t.Fatalf("新要求不应出现在 \"s1\" 名下，out=%q", out)
76		}
77	
78		// 两名学生各自核对：新要求未满足、都没有学分，未满足要求编号按
79		// 各自原文列出。
80		out, _, code = runCLI(t, file, "check", " s1 ")
81		if code != 0 || !strings.Contains(out, "总学分：0") ||
82			!strings.Contains(out, "未满足要求：[ r1 ]") {
83			t.Fatalf("\" s1 \" 应为 0 学分且 \" r1 \" 未满足，code=%d out=%q", code, out)
84		}
85		out, _, code = runCLI(t, file, "check", "s1")
86		if code != 0 || !strings.Contains(out, "总学分：0") ||
87			!strings.Contains(out, "未满足要求：[r1]") {
88			t.Fatalf("\"s1\" 应仍为 0 学分且 r1 未满足，code=%d out=%q", code, out)
89		}
90	}
91	
92	// TestCLIReqWhitespaceDistinctReqIDDifferentCourses 同一学生名下
93	// "r1" 与 " r1 " 是两项要求，但仍须指向不同课程：换课程可并存；
94	// 同一完整编号改指课程整次拒绝；同一课程换编号再建也拒绝。
95	func TestCLIReqWhitespaceDistinctReqIDDifferentCourses(t *testing.T) {
96		d := &diskRecord{
97			Version: 1,
98			Courses: []diskCourse{
99				{ID: "c1", Name: "高等数学", Credit: 4, Open: true},
100				{ID: "c2", Name: "大学物理", Credit: 3, Open: true},
101			},
102			Students: []diskStudent{{ID: "s1"}},
103			Requirements: []diskReq{
104				{ID: "r1", Student: "s1", Course: "c1"},
105			},
106		}
107		file, _ := writeDiskRecord(t, d)
108	
109		// " r1 " 指向另一门课程 c2：作为独立要求新建。
110		out, errText, code := runCLI(t, file, "req", "s1", " r1 ", "c2")
111		if code != 0 || !strings.Contains(out, "已为学生 s1 登记要求  r1 ，指向课程 c2") {
112			t.Fatalf("同号不同空白的要求指向不同课程应允许，code=%d out=%q err=%q",
113				code, out, errText)
114		}
115		show, _, _ := runCLI(t, file, "show", "s1")
116		if !strings.Contains(show, "要求 r1 -> 课程 c1《高等数学》4 学分") ||
117			!strings.Contains(show, "要求  r1  -> 课程 c2《大学物理》3 学分") {
118			t.Fatalf("两项要求应各自保留并显示对应课程，show=%q", show)
119		}
120	
121		before := mustReadRecord(t, file)
122	
123		// 同一完整要求编号 " r1 " 改指 c1：整次拒绝，保留原指向 c2。
124		out, errText, code = runCLI(t, file, "req", "s1", " r1 ", "c1")
125		if code != exitRejected || !strings.Contains(errText, "不能改指") {
126			t.Fatalf("同一要求编号改指课程应拒绝，code=%d out=%q err=%q",
127				code, out, errText)
128		}
129		if strings.Contains(out, "已为学生") || strings.Contains(out, "返回原记录") {
130			t.Fatalf("被拒绝时 stdout 不应出现登记成功或返回原要求的提示，out=%q", out)
131		}
132		assertRecordUnchanged(t, file, before, "改指拒绝：")
133		show, _, _ = runCLI(t, file, "show", "s1")
134		if !strings.Contains(show, "要求  r1  -> 课程 c2《大学物理》3 学分") ||
135			strings.Contains(show, "要求  r1  -> 课程 c1") {
136			t.Fatalf("拒绝改指后 \" r1 \" 应仍指向 c2，show=%q", show)
137		}
138	
139		// 同一学生就同一课程换要求编号再建：拒绝。
140		out, errText, code = runCLI(t, file, "req", "s1", "r2", "c1")
141		if code != exitRejected || !strings.Contains(errText, "重复建立") {
142			t.Fatalf("同一学生就同一课程换编号再建应拒绝，code=%d out=%q err=%q",
143				code, out, errText)
144		}
145		if strings.Contains(out, "已为学生") {
146			t.Fatalf("被拒绝时不应输出登记成功提示，out=%q", out)
147		}
148		assertRecordUnchanged(t, file, before, "同课程换编号拒绝：")
149	}
150	
151	// TestCLIReqWhitespaceExactIdempotent 完整学生编号、要求编号、课程编号
152	// 均与已有要求相同时返回原记录，不新增要求、不改写文件；任一编号的
153	// 空白不同都不能算同一条记录。
154	func TestCLIReqWhitespaceExactIdempotent(t *testing.T) {
155		file, _ := writeDiskRecord(t, reqWhitespaceCLIRecord())
156		// 先建立 " s1 " 的 " r1 " -> " c1 "。
157		if _, _, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 "); code != 0 {
158			t.Fatal("首次登记应成功")
159		}
160		before := mustReadRecord(t, file)
161	
162		out, errText, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 ")
163		if code != 0 || !strings.Contains(out, "已存在且内容一致，返回原记录") {
164			t.Fatalf("完整三元组重复应返回原记录，code=%d out=%q err=%q", code, out, errText)
165		}
166		assertRecordUnchanged(t, file, before, "幂等重复：")
167	
168		// 学生编号去掉空白：命中的是另一名学生 "s1"——其名下没有 " r1 "，
169		// 且课程若写 " c1 " 对 "s1" 是新课程；但三元组无论如何都不等于
170		// 已有记录。这里要求 " r1 " 对 "s1" 尚不存在、课程 " c1 " 存在，
171		// 同时 "s1" 尚未就 " c1 " 建立要求，所以它会作为另一名学生名下
172		// 的独立新要求成功——这正是“编号按完整文字区分”的体现。
173		out, _, code = runCLI(t, file, "req", "s1", " r1 ", " c1 ")
174		if code != 0 || !strings.Contains(out, "已为学生 s1 登记要求  r1 ，指向课程  c1 ") {
175			t.Fatalf("\"s1\" 与 \" s1 \" 是两名学生，同号要求应各自独立，code=%d out=%q",
176				code, out)
177		}
178	}
179	
180	// TestCLIReqWhitespaceIDRejected 完整编号找不到时按业务拒绝：退出码 1，
181	// stderr 指出是学生还是课程不存在，stdout 不出现登记成功或返回原要求
182	// 的提示；不借用去空白后能碰上的记录、不自动创建；空字符串编号与只含
183	// 空白的要求编号同样拒绝；记录文件逐字节保持原样。
184	func TestCLIReqWhitespaceIDRejected(t *testing.T) {
185		// 学生用例：文件里只有 "s1"。
186		dStudent := &diskRecord{
187			Version: 1,
188			Courses: []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
189			Students: []diskStudent{
190				{ID: "s1"},
191			},
192		}
193		// 课程用例：有两名学生但只有课程 "c1"。
194		dCourse := &diskRecord{
195			Version: 1,
196			Courses: []diskCourse{{ID: "c1", Name: "高等数学", Credit: 4, Open: true}},
197			Students: []diskStudent{
198				{ID: "s1"},
199				{ID: " s1 "},
200			},
201		}
202	
203		cases := []struct {
204			label   string
205			d       *diskRecord
206			args    []string
207			wantErr []string
208		}{
209			// 学生编号带前后空白：应明确报告学生不存在。
210			{"学生前导空格", dStudent, []string{"req", " s1", "r1", "c1"}, []string{"学生", "不存在"}},
211			{"学生尾随空格", dStudent, []string{"req", "s1 ", "r1", "c1"}, []string{"学生", "不存在"}},
212			{"学生制表符", dStudent, []string{"req", "\ts1\t", "r1", "c1"}, []string{"学生", "不存在"}},
213			{"学生全角空格", dStudent, []string{"req", "　s1　", "r1", "c1"}, []string{"学生", "不存在"}},
214			// 课程编号带前后空白：应明确报告课程不存在，不借用 "c1"。
215			{"课程前导空格", dCourse, []string{"req", " s1 ", "r1", " c1"}, []string{"课程", "不存在"}},
216			{"课程尾随空格", dCourse, []string{"req", " s1 ", "r1", "c1 "}, []string{"课程", "不存在"}},
217			{"课程制表符", dCourse, []string{"req", " s1 ", "r1", "\tc1\t"}, []string{"课程", "不存在"}},
218			{"课程全角空格", dCourse, []string{"req", " s1 ", "r1", "　c1　"}, []string{"课程", "不存在"}},
219			// 空字符串编号仍拒绝。
220			{"学生空字符串", dStudent, []string{"req", "", "r1", "c1"}, []string{"不能为空"}},
221			{"要求空字符串", dStudent, []string{"req", "s1", "", "c1"}, []string{"不能为空"}},
222			{"课程空字符串", dStudent, []string{"req", "s1", "r1", ""}, []string{"不能为空"}},
223			// 要求编号全部由空白字符组成时拒绝。
224			{"要求编号全空格", dStudent, []string{"req", "s1", "  ", "c1"}, []string{"要求编号"}},
225			{"要求编号制表符", dStudent, []string{"req", "s1", "\t", "c1"}, []string{"要求编号"}},
226			{"要求编号全角空格", dStudent, []string{"req", "s1", "　", "c1"}, []string{"要求编号"}},
227		}
228		for _, tc := range cases {
229			t.Run(tc.label, func(t *testing.T) {
230				file, raw := writeDiskRecord(t, tc.d)
231				out, errText, code := runCLI(t, file, tc.args...)
232				if code != exitRejected {
233					t.Fatalf("%s：应业务拒绝（退出码 1），code=%d out=%q err=%q",
234						tc.label, code, out, errText)
235				}
236				if strings.Contains(out, "已为学生") || strings.Contains(out, "返回原记录") {
237					t.Fatalf("%s：被拒绝时 stdout 不应有登记成功或返回原要求的提示，out=%q",
238						tc.label, out)
239				}
240				for _, want := range tc.wantErr {
241					if !strings.Contains(errText, want) {
242						t.Fatalf("%s：错误输出应包含 %q，err=%q", tc.label, want, errText)
243					}
244				}
245				assertFileByteIdentical(t, file, raw, tc.label+"：")
246			})
247		}
248	}
249	
250	// TestCLIReqWhitespaceExistingRecordsUntouched 已有带空白编号的合法
251	// 记录继续可读：被拒绝的登记不能改写、合并或重新解释其中的要求，冲突
252	// 前后记录文件逐字节一致。
253	func TestCLIReqWhitespaceExistingRecordsUntouched(t *testing.T) {
254		file, _ := writeDiskRecord(t, reqWhitespaceCLIRecord())
255	
256		// 先在 " s1 " 名下建立 " r1 " -> " c1 "。
257		if _, _, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 "); code != 0 {
258			t.Fatal("首次登记应成功")
259		}
260	
261		// 同一完整要求编号改指另一门课程：整次拒绝，文件逐字节保持原样。
262		before := mustReadRecord(t, file)
263		out, errText, code := runCLI(t, file, "req", " s1 ", " r1 ", "c1")
264		if code != exitRejected || !strings.Contains(errText, "不能改指") {
265			t.Fatalf("改指应拒绝，code=%d out=%q err=%q", code, out, errText)
266		}
267		if strings.Contains(out, "已为学生") || strings.Contains(out, "返回原记录") {
268			t.Fatalf("被拒绝时 stdout 不应有登记成功或返回原要求的提示，out=%q", out)
269		}
270		assertRecordUnchanged(t, file, before, "改指拒绝：")
271	
272		// 重新打开记录：带空白的编号原文（" s1 "、" r1 "、" c1 "）仍在，
273		// 没有被修剪或合并；"s1" 的 r1 -> c1 也保持原样。
274		out, _, code = runCLI(t, file, "show", " s1 ")
275		if code != 0 || !strings.Contains(out, "要求  r1  -> 课程  c1 《大学物理》3 学分") {
276			t.Fatalf("已有带空白编号的记录应原样保留，code=%d out=%q", code, out)
277		}
278		out, _, _ = runCLI(t, file, "show", "s1")
279		if !strings.Contains(out, "要求 r1 -> 课程 c1《高等数学》4 学分") {
280			t.Fatalf("\"s1\" 的原要求应保持，out=%q", out)
281		}
282	}
283	
284	// TestCLIReqWhitespaceClosedCourseAllowed 课程停开不改变建立要求的
285	// 规则：停开课程仍可登记要求，新要求不带来学分，show 仍显示课程名称
286	// 与学分；只是之后不能在该要求上新增修读。
287	func TestCLIReqWhitespaceClosedCourseAllowed(t *testing.T) {
288		d := &diskRecord{
289			Version: 1,
290			Courses: []diskCourse{
291				{ID: " c1 ", Name: "大学物理", Credit: 3, Open: false},
292			},
293			Students: []diskStudent{{ID: " s1 "}},
294		}
295		file, _ := writeDiskRecord(t, d)
296	
297		out, errText, code := runCLI(t, file, "req", " s1 ", " r1 ", " c1 ")
298		if code != 0 || !strings.Contains(out, "已为学生  s1  登记要求  r1 ，指向课程  c1 ") {
299			t.Fatalf("停开课程仍应允许登记要求，code=%d out=%q err=%q", code, out, errText)
300		}
301	
302		// 新要求本身不带来学分、未满足。
303		out, _, code = runCLI(t, file, "check", " s1 ")
304		if code != 0 || !strings.Contains(out, "总学分：0") ||
305			!strings.Contains(out, "未满足要求：[ r1 ]") {
306			t.Fatalf("新要求应未满足且不计学分，code=%d out=%q", code, out)
307		}
308		// show 仍按课程记录显示名称与学分（停开只是不能新增修读）。
309		out, _, _ = runCLI(t, file, "show", " s1 ")
310		if !strings.Contains(out, "要求  r1  -> 课程  c1 《大学物理》3 学分") {
311			t.Fatalf("show 应显示实际指向课程的名称与学分，out=%q", out)
312		}
313		// 后续满足途径仍按既有规则：停开课程不能新增修读。
314		out, errText, code = runCLI(t, file, "enroll", " s1 ", " r1 ", "2024春", "e1")
315		if code != exitRejected || !strings.Contains(errText, "停开") {
316			t.Fatalf("停开课程应不能新增修读，code=%d out=%q err=%q", code, out, errText)
317		}
318	}
